const REG_ANIM_CSS = `
@keyframes reg-shine-sweep {
  0%   { transform: translateX(-60px); opacity: 0; }
  8%   { opacity: 1; }
  40%  { transform: translateX(285px); opacity: 1; }
  41%, 100% { transform: translateX(285px); opacity: 0; }
}
@keyframes reg-bar-glow {
  0%, 100% { filter: drop-shadow(0 0 0 rgba(74,222,128,0)); }
  50%      { filter: drop-shadow(0 0 5px rgba(74,222,128,.95)); }
}
@keyframes reg-bracket-flash {
  0%, 100% { fill: #fdfdfd; stroke: #fff; }
  50%      { fill: #4ade80; stroke: #4ade80; }
}
.reg-shine   { animation: reg-shine-sweep 3.6s ease-in-out infinite; }
.reg-bar     { animation: reg-bar-glow 2.2s ease-in-out infinite; }
.reg-bracket { animation: reg-bracket-flash 2.2s ease-in-out infinite; }
.group:hover .reg-shine { animation-duration: 1.4s; }
@media (prefers-reduced-motion: reduce) {
  .reg-shine, .reg-bar, .reg-bracket { animation: none; }
  .reg-shine { opacity: 0; }
}
`;

function RegistrationButton({
  className = "",
  children = "Registration",
  ...props
}) {
  const uid = useId().replace(/:/g, "");
  const maskId = `reg-mask-${uid}`;
  const clipId = `reg-clip-${uid}`;
  const shineClipId = `reg-shine-clip-${uid}`;
  const shineGradId = `reg-shine-grad-${uid}`;

  return (
    <Link
      to="/register"
      className={`relative inline-flex items-center justify-center group cursor-pointer ${className}`}
      {...props}
    >
      <style>{REG_ANIM_CSS}</style>
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 253 74"
        fill="none"
        className="w-36 md:w-44 h-auto transition-transform duration-300 group-hover:scale-105"
      >
        <path d={REG.bar} fill="#FDFDFD" className="reg-bar" />
        <mask
          id={maskId}
          maskUnits="userSpaceOnUse"
          x="-0.978027"
          y="-0.721863"
          width="241"
          height="75"
          fill="black"
        >
          <rect
            fill="white"
            x="-0.978027"
            y="-0.721863"
            width="241"
            height="75"
          />
          <path d={REG.outline} />
        </mask>
        <path
          d={REG.outline}
          strokeWidth="2.54237"
          stroke="white"
          mask={`url(#${maskId})`}
        />
        <foreignObject
          x="-18.3172"
          y="-31.7727"
          width="289.227"
          height="137.366"
        >
          <div
            className="w-full h-full bg-[linear-gradient(0deg,#737373_0%,#737373_100%),rgba(51,51,51,0.30)] bg-blend-overlay"
            style={{ clipPath: `url(#${clipId})` }}
          />
        </foreignObject>
        <path
          d={REG.bracket}
          fill="#FDFDFD"
          strokeWidth="0.847458"
          stroke="white"
          className="reg-bracket"
        />
        {/* light sweep, clipped to the button outline */}
        <g clipPath={`url(#${shineClipId})`} style={{ pointerEvents: "none" }}>
          <polygon
            points="22,-2 48,-2 26,76 0,76"
            fill={`url(#${shineGradId})`}
            className="reg-shine"
          />
        </g>
        <defs>
          <clipPath id={shineClipId}>
            <path d={REG.outline} />
          </clipPath>
          <linearGradient id={shineGradId} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor="#4ade80" stopOpacity="0" />
            <stop offset="0.5" stopColor="#ffffff" stopOpacity="0.55" />
            <stop offset="1" stopColor="#4ade80" stopOpacity="0" />
          </linearGradient>
          <clipPath id={clipId} transform="translate(18.3172 31.7727)">
            <path d={REG.blurClip} />
          </clipPath>
        </defs>
      </svg>
      <span className="absolute inset-0 flex items-center justify-center pl-3 text-xs md:text-sm font-jakarta font-semibold tracking-wide text-white">
        {children}
      </span>
    </Link>
  );
}

const NAV_ITEMS = [
  { id: "home", to: "/", label: "HOME" },
  { id: "cooldown", scroll: "cooldown", label: "COOLDOWN" },
  { id: "department", label: "DEPARTMENTS", menu: true },
  { id: "about", scroll: "about", label: "ABOUT" },
  { id: "footer", scroll: "footer", label: "FOOTER" },
];

const ITEM =
  "relative flex items-center gap-1.5 text-xs lg:text-sm tracking-[0.18em] font-jakarta font-semibold transition-colors duration-200 cursor-pointer";
const ITEM_ON = "text-white";
const ITEM_OFF = "text-neutral-300 hover:text-green-300";
const PANEL =
  "rounded-2xl bg-neutral-950/90 backdrop-blur-sm border border-white/15 shadow-[inset_0_1px_0_rgba(255,255,255,0.18),0_8px_20px_rgba(0,0,0,0.6)]";

const Underline = () => (
  <span className="absolute -bottom-1.5 left-1/2 -translate-x-1/2 w-4 h-[2px] bg-green-400 rounded-full shadow-[0_0_8px_#4ade80]" />
);

const Chevron = ({ open, className = "w-3 h-3" }) => (
  <svg
    className={`${className} transition-transform duration-300 ${open ? "rotate-180 text-green-400" : "text-neutral-400"}`}
    fill="none"
    viewBox="0 0 24 24"
    stroke="currentColor"
    aria-hidden="true"
  >
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={2.5}
      d="M19 9l-7 7-7-7"
    />
  </svg>
);

function DesktopDepartmentMenu({ label, departments, active, pathname }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => setOpen(false), [pathname]);

  useEffect(() => {
    if (!open) return;
    const onDown = (e) => !ref.current?.contains(e.target) && setOpen(false);
    const onKey = (e) => e.key === "Escape" && setOpen(false);
    document.addEventListener("pointerdown", onDown);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  const hover = (value) => (e) => e.pointerType === "mouse" && setOpen(value);

  return (
    <div
      ref={ref}
      className="relative"
      onPointerEnter={hover(true)}
      onPointerLeave={hover(false)}
    >
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen(true)}
        className={`${ITEM} ${active ? ITEM_ON : ITEM_OFF}`}
      >
        <span>{label}</span>
        <Chevron open={open} />
        {active && <Underline />}
      </button>

      {open && (
        <div className="absolute top-full left-1/2 -translate-x-1/2 pt-3 z-50 animate-in fade-in slide-in-from-top-2 duration-200">
          <div className={`w-60 p-2 flex flex-col gap-1 ${PANEL}`}>
            {departments.map((dept) => {
              const current = pathname === dept.path;
              return (
                <Link
                  key={dept.id}
                  to={dept.path}
                  aria-current={current ? "page" : undefined}
                  className={`group flex items-center justify-between px-3 py-2 rounded-xl border transition-colors duration-200 ${
                    current
                      ? "bg-green-500/20 text-green-200 border-green-400/30"
                      : "text-neutral-300 hover:text-white hover:bg-white/5 border-transparent"
                  }`}
                >
                  <span className="flex flex-col">
                    <span className="text-xs font-jakarta font-bold tracking-wider group-hover:text-green-300 transition-colors">
                      {dept.label}
                    </span>
                    <span className="text-[10px] text-neutral-400 font-jakarta font-normal">
                      {dept.desc}
                    </span>
                  </span>
                  <span
                    className={`w-1.5 h-1.5 rounded-full transition-colors duration-200 ${current ? "bg-green-400 shadow-[0_0_8px_#4ade80]" : "bg-transparent group-hover:bg-green-400/60"}`}
                  />
                </Link>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

function MobileDrawer({
  departments,
  pathname,
  isActive,
  onClose,
  onScrollClick,
}) {
  const [deptOpen, setDeptOpen] = useState(false);
  const row = (on) =>
    `flex items-center justify-between text-left text-xs tracking-[0.2em] font-jakarta font-semibold py-2 px-3 rounded-lg transition-colors ${
      on
        ? "bg-green-500/20 text-green-300 border-l-2 border-green-400"
        : "text-neutral-300 hover:text-white hover:bg-white/5"
    }`;

  return (
    <div
      className={`md:hidden mt-3 max-w-md mx-auto p-4 flex flex-col gap-2.5 animate-in fade-in slide-in-from-top-4 duration-200 ${PANEL}`}
    >
      {NAV_ITEMS.map((item) =>
        item.menu ? (
          <div key={item.id} className="flex flex-col">
            <button
              type="button"
              aria-expanded={deptOpen}
              onClick={() => setDeptOpen((v) => !v)}
              className={row(isActive(item))}
            >
              <span>{item.label}</span>
              <Chevron open={deptOpen} className="w-3.5 h-3.5" />
            </button>
            {deptOpen && (
              <div className="ml-3 mt-1 pl-3 pr-1 py-1.5 flex flex-col gap-1 border-l-2 border-green-500/30">
                {departments.map((dept) => {
                  const current = pathname === dept.path;
                  return (
                    <Link
                      key={dept.id}
                      to={dept.path}
                      onClick={onClose}
                      aria-current={current ? "page" : undefined}
                      className={`flex items-center justify-between py-1.5 px-2.5 rounded-lg text-xs font-jakarta font-medium transition-colors ${
                        current
                          ? "text-green-300 bg-green-500/15"
                          : "text-neutral-400 hover:text-white hover:bg-white/5"
                      }`}
                    >
                      <span>{dept.label}</span>
                      {current && (
                        <span className="w-1.5 h-1.5 rounded-full bg-green-400 shadow-[0_0_6px_#4ade80]" />
                      )}
                    </Link>
                  );
                })}
              </div>
            )}
          </div>
        ) : item.scroll ? (
          <button
            key={item.id}
            type="button"
            onClick={(e) => {
              onClose();
              onScrollClick(item.scroll)(e);
            }}
            className={`${row(false)} w-full cursor-pointer`}
          >
            {item.label}
          </button>
        ) : (
          <Link
            key={item.id}
            to={item.to}
            onClick={onClose}
            aria-current={isActive(item) ? "page" : undefined}
            className={row(isActive(item))}
          >
            {item.label}
          </Link>
        ),
      )}
      <div className="pt-2 border-t border-white/10 flex justify-center">
        <RegistrationButton className="w-full" />
      </div>
    </div>
  );
}

export default function Navbar({ departments = DEPARTMENT_LINKS }) {
  const { pathname, hash } = useLocation();
  const navigate = useNavigate();

  // Smooth-scroll to a section on the current page, or go home first
  // (then the hash effect below does the scrolling).
  const scrollToSection = (id) => (e) => {
    if (e && e.preventDefault) e.preventDefault();
    const el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({ behavior: "smooth", block: "start" });
      window.history.replaceState(null, "", `${pathname}#${id}`);
    } else {
      navigate(`/#${id}`);
    }
  };

  // Arriving on a page with a #hash (e.g. /register -> /#about, or a
  // direct link) -> scroll to that section once it has rendered.
  useEffect(() => {
    if (!hash) return;
    const t = setTimeout(() => {
      document
        .getElementById(hash.slice(1))
        ?.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 100);
    return () => clearTimeout(t);
  }, [pathname, hash]);
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => setMobileOpen(false), [pathname]);

  const deptActive = departments.some((d) => d.path === pathname);
  const isActive = (item) =>
    item.menu
      ? deptActive
      : pathname === item.to ||
        pathname.startsWith(`${item.to}/`) ||
        (item.id === "home" && pathname === "/");

  return (
    <header
      data-anim="navbar"
      className="relative z-40 w-full pt-3 sm:pt-4 md:pt-6 px-3 sm:px-6 lg:px-8 xl:px-12"
    >
      <nav className="max-w-[1680px] mx-auto flex items-center justify-between md:grid md:grid-cols-[1fr_auto_1fr] rounded-xl sm:rounded-2xl bg-neutral-950/40 backdrop-blur-[8px] border border-white/15 px-3 sm:px-5 md:px-6 py-2 sm:py-2.5 transition-colors duration-300 hover:border-green-400/40">
        <Link
          to="/"
          aria-label="Home"
          className="flex items-center gap-2 group md:justify-self-start"
        >
          <HunterLogo className="h-7 sm:h-8 md:h-10 w-auto" />
          <img
            src="/LogoV.svg"
            alt="OMC logo"
            draggable={false}
            className="h-7 sm:h-8 md:h-10 w-auto select-none transition-transform duration-300 group-hover:scale-105"
          />
        </Link>

        <div className="hidden md:flex items-center gap-4 lg:gap-8">
          {NAV_ITEMS.map((item) => {
            const on = isActive(item);
            if (item.menu) {
              return (
                <DesktopDepartmentMenu
                  key={item.id}
                  label={item.label}
                  departments={departments}
                  active={on}
                  pathname={pathname}
                />
              );
            }
            if (item.scroll) {
              const cls = `${ITEM} ${ITEM_OFF}`;
              return (
                <button
                  key={item.id}
                  type="button"
                  onClick={scrollToSection(item.scroll)}
                  className={cls}
                >
                  {item.label}
                </button>
              );
            }
            const cls = `${ITEM} ${on ? ITEM_ON : ITEM_OFF}`;
            return (
              <Link
                key={item.id}
                to={item.to}
                aria-current={on ? "page" : undefined}
                className={cls}
              >
                {item.label}
                {on && <Underline />}
              </Link>
            );
          })}
        </div>

        <div className="hidden md:flex items-center md:justify-self-end">
          <RegistrationButton />
        </div>

        <button
          type="button"
          onClick={() => setMobileOpen((v) => !v)}
          aria-label="Toggle navigation menu"
          aria-expanded={mobileOpen}
          className="md:hidden p-1.5 text-neutral-200 hover:text-green-400 focus-visible:outline-2 focus-visible:outline-green-400 transition-colors"
        >
          <svg
            className="w-6 h-6"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d={mobileOpen ? "M6 18L18 6M6 6l12 12" : "M4 6h16M4 12h16m-7 6h7"}
            />
          </svg>
        </button>
      </nav>

      {mobileOpen && (
        <MobileDrawer
          departments={departments}
          pathname={pathname}
          isActive={isActive}
          onClose={() => setMobileOpen(false)}
          onScrollClick={scrollToSection}
        />
      )}
    </header>
  );
}

export { HunterLogo, RegistrationButton };
